use gram_panchayat;
show tables;
select * from citizen;
select * from certificate_type;
select * from certificate_application;
select * from panchayat_office;
select count(*) as total_applications from certificate_application;
select count(*) as total_citizens from citizen;
select count(*) as different_certificate_types from certificate_type;
select min(application_date) as earliest_application_date from certificate_application;
select max(application_date) as latest_application_date from certificate_application;
select application_status,count(*) as total_applications from certificate_application group by application_status;
select certificate_type_id,count(*) as total_applications from certificate_type group by certificate_type_id;
select office_id,count(*) as total_applications from certificate_application group by office_id;
select village_name,count(*) as total_citizens from citizen group by village_name;
select application_date,count(*) as total_applications from certificate_application group by application_date;
select certificate_id,office_id,count(*) as total_applications from certificate_application group by certificate_id,office_id;
select ct.certificate_name,count(*) as total_applications from certificate_application ca inner join certificate_type ct on ca.certificate_id=ct.certificate_type_id group by ct.certificate_name;
select po.office_name,count(*) as total_applications from certificate_application ca inner join panchayat_office po on ca.office_id=po.office_id group by po.office_name;
select ct.certificate_name,count(*) as total_applications from certificate_application ca inner join certificate_type ct on ca.certificate_id=ct.certificate_type_id group by ct.certificate_name having count(*)>2;
select po.office_name,count(*) as total_applications from certificate_application ca inner join panchayat_office po on ca.office_id=po.office_id group by po.office_name having count(*)>2;
select ct.certificate_name,count(*) as total_applications from certificate_application ca inner join certificate_type ct on ca.certificate_id=ct.certificate_type_id group by ct.certificate_name order by total_applications desc;
select po.office_name,count(*) as total_applications from certificate_application ca inner join panchayat_office po on ca.office_id=po.office_id group by po.office_name order by total_applications asc;
select ct.certificate_name,count(*) as total_applications from certificate_application ca inner join certificate_type ct on ca.certificate_id=ct.certificate_type_id group by ct.certificate_name order by total_applications desc;
select ct.certificate_name,count(*) as total_applications from certificate_application ca inner join certificate_type ct on ca.certificate_id=ct.certificate_type_id group by ct.certificate_name having count(*)>2 order by total_applications desc;
select ct.certificate_name,count(*) as total_applications from certificate_application ca inner join certificate_type ct on ca.certificate_id=ct.certificate_type_id inner join panchayat_office po on ca.office_id=po.office_id group by ct.certificate_name,po.office_name order by total_applications desc limit 1;
select application_status,count(*) as total_applications from certificate_application group by application_status order by total_applications desc limit 1;
select application_status,count(*) as total_applications from certificate_application group by application_status order by total_applications asc limit 1;